ElevatedCard( modifier = Modifier.weight(1f), shape = RoundedCornerShape(16.dp) ) { if (logs.isEmpty()) { Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) { Text(text = "No logs yet", style = MaterialTheme.typography.bodyLarge) } } else { LazyColumn( modifier = Modifier.fillMaxSize(), contentPadding = PaddingValues(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp) ) { items(logs) { entry -> Surface( shape = RoundedCornerShape(12.dp), color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.35f) ) { Column(modifier = Modifier.padding(12.dp)) { Row( modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween ) { Text( text = entry.appName, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary ) Column(horizontalAlignment = Alignment.End) { Text( text = dateFormatter.format(Date(entry.timestamp)), style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant ) if (entry.endTime > entry.timestamp) { val durationSec = (entry.endTime - entry.timestamp) / 1000 Text( text = "Duration: ${durationSec}s", style = MaterialTheme.typography.labelSmall, fontWeight = FontWeight.SemiBold, color = MaterialTheme.colorScheme.secondary ) } } } Spacer(modifier = Modifier.size(4.dp)) Text( text = entry.content, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface ) Text( text = entry.packageName, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f) ) } } } } } } Row( modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp) ) { OutlinedButton( onClick = { AnalyticsManager.logAction("clear_logs") showClearLogsDialog = true }, enabled = logs.isNotEmpty(), modifier = Modifier.weight(1f), shape = RoundedCornerShape(14.dp), colors = ButtonDefaults.outlinedButtonColors( disabledContainerColor = MaterialTheme.colorScheme.surface.copy(alpha = 0.3f), disabledContentColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.38f) ) ) { Text("Clear Logs") } Button( onClick = onBack, modifier = Modifier.weight(1f), shape = RoundedCornerShape(14.dp) ) { Text("Back") } } }
if (showClearLogsDialog) { AlertDialog( onDismissRequest = { showClearLogsDialog = false }, title = { Text("Clear logs?") }, text = { Text("Are you sure you want to clear all AD Detection Logs? This action cannot be undone.") }, confirmButton = { TextButton( onClick = { AdMuteSettings.clearAdLogs(context) logs = emptyList() showClearLogsDialog = false } ) { Text("Clear") } }, dismissButton = { TextButton(onClick = { showClearLogsDialog = false }) { Text("Cancel") } } ) } }
