val previousValue = (minutes - 1).takeIf { it >= minValue } val nextValue = (minutes + 1).takeIf { it <= maxValue } val previousAlpha by animateFloatAsState(targetValue = if (previousValue == null) 0f else 0.5f, label = "prev-alpha") val nextAlpha by animateFloatAsState(targetValue = if (nextValue == null) 0f else 0.5f, label = "next-alpha")
Column( modifier = modifier.pointerInput(minutes) { detectVerticalDragGestures( onVerticalDrag = { change, dragAmount -> accumulatedDrag += dragAmount val stepThresholdPx = 24f
while (abs(accumulatedDrag) >= stepThresholdPx) { val steppingDown = accumulatedDrag > 0 val candidate = if (steppingDown) minutes - 1 else minutes + 1 onValueChange(candidate.coerceIn(minValue, maxValue)) accumulatedDrag += if (steppingDown) -stepThresholdPx else stepThresholdPx } change.consume() }, onDragEnd = { accumulatedDrag = 0f }, onDragCancel = { accumulatedDrag = 0f } ) }, horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(2.dp) ) { Text( text = previousValue?.toString() ?: "", style = MaterialTheme.typography.titleMedium, color = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.alpha(previousAlpha) ) AnimatedContent( targetState = minutes, transitionSpec = { if (targetState > initialState) { (slideInVertically { it / 2 } + fadeIn() + scaleIn(initialScale = 0.82f)) .togetherWith(slideOutVertically { -it / 2 } + fadeOut() + scaleOut(targetScale = 1.18f)) } else { (slideInVertically { -it / 2 } + fadeIn() + scaleIn(initialScale = 0.82f)) .togetherWith(slideOutVertically { it / 2 } + fadeOut() + scaleOut(targetScale = 1.18f)) } }, label = "cooldown-roller" ) { value -> Text( text = value.toString(), style = MaterialTheme.typography.displayMedium, fontWeight = FontWeight.Bold ) } Text( text = nextValue?.toString() ?: "", style = MaterialTheme.typography.titleMedium, color = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.alpha(nextAlpha) ) } }
@Composable private fun NotificationSoundSettingsScreen( currentSettings: NotificationSoundSettings, onSave: (NotificationSoundSettings) -> Unit, onBack: () -> Unit, modifier: Modifier = Modifier ) { var inSound by remember(currentSettings) { mutableStateOf(currentSettings.inSound) } var outSound by remember(currentSettings) { mutableStateOf(currentSettings.outSound) } val context = LocalContext.current val isLandscape = LocalConfiguration.current.orientation == Configuration.ORIENTATION_LANDSCAPE var previewPlayer by remember { mutableStateOf<MediaPlayer?>(null) }
fun stopPreview() { previewPlayer?.release() previewPlayer = null }
fun playPreview(config: NotificationSoundConfig) { stopPreview() when (config.source) { NotificationSoundSource.OFF -> Unit NotificationSoundSource.STOCK -> { runCatching { val attributes = AudioAttributes.Builder() .setUsage(AudioAttributes.USAGE_NOTIFICATION) .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION) .build() val player = MediaPlayer.create(context, config.stockSound.resId, attributes, 0) ?: return@runCatching previewPlayer = player player.setOnCompletionListener { if (previewPlayer === it) previewPlayer = null it.release() } player.setOnErrorListener { mp, _, _ -> if (previewPlayer === mp) previewPlayer = null mp.release() true } player.start() } } NotificationSoundSource.CUSTOM -> { val uriText = config.customUri ?: return runCatching { val player = MediaPlayer().apply { setDataSource(context, uriText.toUri()) setAudioAttributes( AudioAttributes.Builder() .setUsage(AudioAttributes.USAGE_NOTIFICATION) .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION) .build() ) setOnCompletionListener { if (previewPlayer === it) previewPlayer = null it.release() } setOnErrorListener { mp, _, _ -> if (previewPlayer === mp) previewPlayer = null mp.release() true } prepare() previewPlayer = this start() } player } } } }
DisposableEffect(Unit) { onDispose { stopPreview() } }
BackHandler { stopPreview() onBack() }
val pickInSoundLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { uri: Uri? -> val updated = uri?.let { context.contentResolver.takePersistablePermissionSafely(it) inSound.copy( source = NotificationSoundSource.CUSTOM, customUri = it.toString(), customDisplayName = context.contentResolver.resolveDisplayName(it) ) } ?: inSound inSound = updated if (uri != null) playPreview(updated) }
val pickOutSoundLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { uri: Uri? -> val updated = uri?.let { context.contentResolver.takePersistablePermissionSafely(it) outSound.copy( source = NotificationSoundSource.CUSTOM, customUri = it.toString(), customDisplayName = context.contentResolver.resolveDisplayName(it) ) } ?: outSound outSound = updated if (uri != null) playPreview(updated) }
AppScreenContainer( title = "Notification sounds", subtitle = "Configure IN (ad detected) and OUT (ad ended) sounds.", modifier = modifier ) { val inSoundSection: @Composable () -> Unit = { SoundConfigSection( title = "IN sound", config = inSound, stockOptions = listOf(StockNotificationSound.S1_IN, StockNotificationSound.S2_IN), onSelectOff = { inSound = inSound.copy(source = NotificationSoundSource.OFF) stopPreview() }, onSelectStock = { selected -> val updated = inSound.copy(source = NotificationSoundSource.STOCK, stockSound = selected) inSound = updated playPreview(updated) }, onSelectCustom = { if (inSound.customUri != null) { val updated = inSound.copy(source = NotificationSoundSource.CUSTOM) inSound = updated playPreview(updated) } }, onPickCustom = { pickInSoundLauncher.launch(arrayOf("audio/*")) }, onClearCustom = { inSound = inSound.copy(customUri = null, customDisplayName = null, source = NotificationSoundSource.OFF) stopPreview() } ) }
val outSoundSection: @Composable () -> Unit = { SoundConfigSection( title = "OUT sound", config = outSound, stockOptions = listOf(StockNotificationSound.S1_OUT, StockNotificationSound.S2_OUT), onSelectOff = { outSound = outSound.copy(source = NotificationSoundSource.OFF) stopPreview() }, onSelectStock = { selected -> val updated = outSound.copy(source = NotificationSoundSource.STOCK, stockSound = selected) outSound = updated playPreview(updated) }, onSelectCustom = { if (outSound.customUri != null) { val updated = outSound.copy(source = NotificationSoundSource.CUSTOM) outSound = updated playPreview(updated) } }, onPickCustom = { pickOutSoundLauncher.launch(arrayOf("audio/*")) }, onClearCustom = { outSound = outSound.copy(customUri = null, customDisplayName = null, source = NotificationSoundSource.OFF) stopPreview() } ) }
if (isLandscape) { Row( modifier = Modifier .weight(1f) .fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp) ) { Column( modifier = Modifier .weight(1f) .verticalScroll(rememberScrollState()) ) { inSoundSection() } Column( modifier = Modifier .weight(1f) .verticalScroll(rememberScrollState()) ) { outSoundSection() } } } else { Column( modifier = Modifier .weight(1f) .verticalScroll(rememberScrollState()), verticalArrangement = Arrangement.spacedBy(10.dp) ) { inSoundSection() outSoundSection() } } Button( onClick = { onSave(NotificationSoundSettings(inSound = inSound, outSound = outSound)) }, modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(14.dp) ) { Text("Save") } OutlinedButton( onClick = { stopPreview() onBack() }, modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(14.dp) ) { Text("Back") } } }
@Composable @OptIn(ExperimentalMaterial3Api::class) private fun SoundConfigSection( title: String, config: NotificationSoundConfig, stockOptions: List<StockNotificationSound>, onSelectOff: () -> Unit, onSelectStock: (StockNotificationSound) -> Unit, onSelectCustom: () -> Unit, onPickCustom: () -> Unit, onClearCustom: () -> Unit ) { data class SoundChoice(val label: String, val action: () -> Unit) val choices = remember(config.customUri, config.customDisplayName, stockOptions) { buildList { add(SoundChoice(label = "Off", action = onSelectOff)) stockOptions.forEach { stock -> add(SoundChoice(label = stock.label, action = { onSelectStock(stock) })) } if (config.customUri != null) { add(SoundChoice(label = config.customDisplayName ?: "Custom sound", action = onSelectCustom)) } } } val selectedLabel = config.summaryLabel() var dropdownExpanded by remember { mutableStateOf(false) }
ElevatedCard(shape = RoundedCornerShape(14.dp)) { Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) { Text(text = title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold) Text( text = "- Select sound", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant ) ExposedDropdownMenuBox( expanded = dropdownExpanded, onExpandedChange = { dropdownExpanded = !dropdownExpanded } ) { OutlinedTextField( value = selectedLabel, onValueChange = {}, readOnly = true, modifier = Modifier .fillMaxWidth() .menuAnchor(type = ExposedDropdownMenuAnchorType.PrimaryNotEditable, enabled = true), trailingIcon = { ExposedDropdownMenuDefaults.TrailingIcon(expanded = dropdownExpanded) }, textStyle = MaterialTheme.typography.bodyLarge ) DropdownMenu( expanded = dropdownExpanded, onDismissRequest = { dropdownExpanded = false } ) { choices.forEach { choice -> DropdownMenuItem( text = { Text(choice.label) }, onClick = { dropdownExpanded = false choice.action.invoke() } ) } } } OutlinedButton(onClick = onPickCustom, modifier = Modifier.fillMaxWidth()) { Text("Upload custom sound") } if (config.customUri != null) { OutlinedButton(onClick = onClearCustom, modifier = Modifier.fillMaxWidth()) { Text("Clear custom sound") } } } } }
private fun loadInstalledApps( packageManager: PackageManager, ownPackageName: String, recommendedPackages: Set<String> ): List<InstalledApp> { val launcherIntent = Intent(Intent.ACTION_MAIN).apply { addCategory(Intent.CATEGORY_LAUNCHER) } val resolveInfos = packageManager.queryIntentActivities(launcherIntent, 0)
val launcherApps = resolveInfos.mapNotNull { info -> val activityInfo = info.activityInfo ?: return@mapNotNull null val packageName = activityInfo.packageName if (packageName == ownPackageName) return@mapNotNull null val label = info.loadLabel(packageManager).toString().ifBlank { packageName } val icon = runCatching { packageManager.getApplicationIcon(packageName) }.getOrNull() InstalledApp(label, packageName, icon?.toBitmapSafely()) }
val recommendedInstalledApps = recommendedPackages.mapNotNull { packageName -> if (packageName == ownPackageName) return@mapNotNull null try { val appInfo = packageManager.getApplicationInfo(packageName, 0) val label = packageManager.getApplicationLabel(appInfo).toString().ifBlank { packageName } val icon = runCatching { packageManager.getApplicationIcon(packageName) }.getOrNull() InstalledApp(label, packageName, icon?.toBitmapSafely()) } catch (_: NameNotFoundException) { null } }
return (launcherApps + recommendedInstalledApps) .distinctBy { it.packageName } .sortedBy { it.label.lowercase() } }
private fun NotificationSoundConfig.summaryLabel(): String { return when (source) { NotificationSoundSource.OFF -> "Off" NotificationSoundSource.STOCK -> stockSound.label NotificationSoundSource.CUSTOM -> customDisplayName ?: "Custom sound" } }
private fun Drawable.toBitmapSafely(): Bitmap { if (this is BitmapDrawable && bitmap != null) { return bitmap } val width = intrinsicWidth.takeIf { it > 0 } ?: 96 val height = intrinsicHeight.takeIf { it > 0 } ?: 96 val bitmap = createBitmap(width, height, Bitmap.Config.ARGB_8888) val canvas = Canvas(bitmap) setBounds(0, 0, canvas.width, canvas.height) draw(canvas) return bitmap }
private fun android.content.ContentResolver.takePersistablePermissionSafely(uri: Uri) { runCatching { takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION) } }
private fun android.content.ContentResolver.resolveDisplayName(uri: Uri): String { return runCatching { query(uri, arrayOf(OpenableColumns.DISPLAY_NAME), null, null, null)?.use { cursor -> val index = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME) if (index >= 0 && cursor.moveToFirst()) { return@runCatching cursor.getString(index) } null } }.getOrNull() ?: "Custom sound" }
