enum class SetupStep { INTRO, WHITELIST, MANAGE_WHITELIST, DETECTION, COOLDOWN, NOTIFICATION_SOUND, LOGS, MODIFY_KEYWORDS, RUNNING, ABOUT, THEME }
data class InstalledApp( val label: String, val packageName: String, val iconBitmap: Bitmap? )
class MainActivity : ComponentActivity() { private var isPostNotificationsGranted by mutableStateOf(false) private var isNotificationAccessGranted by mutableStateOf(false) private var isBatteryOptimizationIgnored by mutableStateOf(false)
private val notificationPermissionLauncher = registerForActivityResult(ActivityResultContracts.RequestPermission()) { isPostNotificationsGranted = hasPostNotificationsPermission() }
override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState) AnalyticsManager.initialize(this) refreshPermissionStates() enableEdgeToEdge() setContent { var themeMode by remember { mutableStateOf(AdMuteSettings.getThemeMode(this@MainActivity)) } val systemDarkTheme = isSystemInDarkTheme() val shouldUseDarkTheme = when (themeMode) { ThemeMode.LIGHT -> false ThemeMode.DARK -> true ThemeMode.SYSTEM -> systemDarkTheme } ADVOIDTheme(darkTheme = shouldUseDarkTheme) { val donationUrl = "https://github.com/sponsors/Longbatman09" var setupStep by remember { mutableStateOf( if (AdMuteSettings.isSetupCompleted(this@MainActivity)) SetupStep.RUNNING else SetupStep.INTRO ) } var showSetupDonationDialog by remember { mutableStateOf(false) } var isPaused by remember { mutableStateOf(AdMuteSettings.isAppPaused(this@MainActivity)) } var selectedWhitelist by remember { mutableStateOf(WhitelistedApps.getSelected(this@MainActivity)) } val isSetupCompleted = remember { AdMuteSettings.isSetupCompleted(this@MainActivity) } var cooldownMinutes by remember { mutableStateOf(AdMuteSettings.getCooldownMinutes(this@MainActivity)) } var notificationSoundMode by remember { mutableStateOf(AdMuteSettings.getNotificationSoundSettings(this@MainActivity)) } val nowPlayingInfo by produceState<NowPlayingInfo?>( initialValue = AdMuteSettings.getNowPlayingInfo(this@MainActivity) ) { while (true) { value = AdMuteSettings.getNowPlayingInfo(this@MainActivity) delay(1000L) } } LaunchedEffect(Unit) { while (true) { val latestPaused = AdMuteSettings.isAppPaused(this@MainActivity) if (latestPaused != isPaused) { isPaused = latestPaused } delay(1000L) } }
BackHandler(enabled = setupStep == SetupStep.WHITELIST || setupStep == SetupStep.MANAGE_WHITELIST) { setupStep = if (isSetupCompleted) { SetupStep.RUNNING } else { SetupStep.INTRO } }
Scaffold(modifier = Modifier.fillMaxSize()) { innerPadding -> AnimatedContent( targetState = setupStep, transitionSpec = { fadeIn(animationSpec = tween(400)) togetherWith fadeOut(animationSpec = tween(350)) }, label = "screen-transition" ) { targetStep -> when (targetStep) { SetupStep.INTRO -> { LaunchedEffect(Unit) { AnalyticsManager.logScreenView("Introduction", "MainActivity") } IntroductionScreen( onStartSetup = { setupStep = SetupStep.WHITELIST }, modifier = Modifier.padding(innerPadding) ) } SetupStep.WHITELIST -> { LaunchedEffect(Unit) { AnalyticsManager.logScreenView("WhitelistSelection", "MainActivity") } WhitelistSelectionScreen( currentSelection = selectedWhitelist, onContinue = { selection -> WhitelistedApps.saveSelected(this@MainActivity, selection) selectedWhitelist = WhitelistedApps.getSelected(this@MainActivity) AnalyticsManager.logSettingsChanged("whitelist", selection.size.toString()) setupStep = SetupStep.DETECTION }, modifier = Modifier.padding(innerPadding) ) } SetupStep.MANAGE_WHITELIST -> { LaunchedEffect(Unit) { AnalyticsManager.logScreenView("ManageWhitelist", "MainActivity") } WhitelistSelectionScreen( currentSelection = selectedWhitelist, continueLabel = "Save and return", onContinue = { selection -> WhitelistedApps.saveSelected(this@MainActivity, selection) selectedWhitelist = WhitelistedApps.getSelected(this@MainActivity) AnalyticsManager.logSettingsChanged("whitelist", selection.size.toString()) setupStep = SetupStep.RUNNING }, modifier = Modifier.padding(innerPadding) ) } SetupStep.DETECTION -> { LaunchedEffect(Unit) { AnalyticsManager.logScreenView("DetectionSetup", "MainActivity") } DetectionSetupScreen( keywordsPreview = AdKeywordRules.all(this@MainActivity).joinToString(), postNotificationsGranted = isPostNotificationsGranted, notificationAccessGranted = isNotificationAccessGranted, batteryOptimizationGranted = isBatteryOptimizationIgnored, onRequestPostNotifications = { if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) { notificationPermissionLauncher.launch(android.Manifest.permission.POST_NOTIFICATIONS) } }, onOpenNotificationAccess = { startActivity(Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS)) }, onRequestDisableBatteryOptimization = { requestDisableBatteryOptimization() }, onSetupComplete = { AdMuteSettings.saveSetupCompleted(this@MainActivity, true) if (!AdMuteSettings.isSetupDonationPromptShown(this@MainActivity)) { showSetupDonationDialog = true AdMuteSettings.saveSetupDonationPromptShown(this@MainActivity, true) } setupStep = SetupStep.RUNNING }, modifier = Modifier.padding(innerPadding) ) } SetupStep.RUNNING, SetupStep.COOLDOWN, SetupStep.LOGS, SetupStep.MODIFY_KEYWORDS, SetupStep.NOTIFICATION_SOUND, SetupStep.ABOUT, SetupStep.THEME -> Box(modifier = Modifier.fillMaxSize()) { LaunchedEffect(setupStep) { val screenName = when(setupStep) { SetupStep.RUNNING -> "Running" SetupStep.COOLDOWN -> "CooldownSettings" SetupStep.LOGS -> "AdLogs" SetupStep.MODIFY_KEYWORDS -> "ModifyKeywords" SetupStep.ABOUT -> "About" SetupStep.THEME -> "ThemeSelection" else -> "Unknown" } AnalyticsManager.logScreenView(screenName, "MainActivity") } RunningScreen( nowPlayingInfo = nowPlayingInfo, onChangeWhitelist = { setupStep = SetupStep.MANAGE_WHITELIST }, onChangeCooldown = { setupStep = SetupStep.COOLDOWN }, onModifyNotificationSounds = { setupStep = SetupStep.NOTIFICATION_SOUND }, onViewLogs = { setupStep = SetupStep.LOGS }, onModifyKeywords = { setupStep = SetupStep.MODIFY_KEYWORDS }, onViewAbout = { setupStep = SetupStep.ABOUT }, onChangeTheme = { setupStep = SetupStep.THEME }, isPaused = isPaused, onPauseToggle = { val newState = !isPaused isPaused = newState AdMuteSettings.saveAppPaused(this@MainActivity, newState) AnalyticsManager.logAction(if (newState) "pause_app" else "resume_app") }, useDarkTheme = shouldUseDarkTheme, modifier = Modifier.padding(innerPadding) ) AnimatedVisibility( visible = setupStep == SetupStep.COOLDOWN, enter = fadeIn(animationSpec = tween(durationMillis = 240)), exit = fadeOut(animationSpec = tween(durationMillis = 220)) ) { CooldownSettingsScreen( currentCooldownMinutes = cooldownMinutes, onSave = { minutes -> AdMuteSettings.saveCooldownMinutes(this@MainActivity, minutes) cooldownMinutes = AdMuteSettings.getCooldownMinutes(this@MainActivity) AnalyticsManager.logSettingsChanged("cooldown_minutes", minutes.toString()) setupStep = SetupStep.RUNNING }, onBack = { setupStep = SetupStep.RUNNING }, modifier = Modifier.padding(innerPadding) ) } AnimatedVisibility( visible = setupStep == SetupStep.LOGS, enter = fadeIn(animationSpec = tween(durationMillis = 240)), exit = fadeOut(animationSpec = tween(durationMillis = 220)) ) { AdLogsScreen( onBack = { setupStep = SetupStep.RUNNING }, modifier = Modifier.padding(innerPadding) ) } AnimatedVisibility( visible = setupStep == SetupStep.MODIFY_KEYWORDS, enter = fadeIn(animationSpec = tween(durationMillis = 240)), exit = fadeOut(animationSpec = tween(durationMillis = 220)) ) { ModifyKeywordsScreen( onBack = { setupStep = SetupStep.RUNNING }, modifier = Modifier.padding(innerPadding) ) } AnimatedVisibility( visible = setupStep == SetupStep.NOTIFICATION_SOUND, enter = fadeIn(animationSpec = tween(durationMillis = 240)), exit = fadeOut(animationSpec = tween(durationMillis = 220)) ) { LaunchedEffect(Unit) { AnalyticsManager.logScreenView("NotificationSoundSettings", "MainActivity") } NotificationSoundSettingsScreen( currentSettings = notificationSoundMode, onSave = { settings -> AdMuteSettings.saveNotificationSoundSettings(this@MainActivity, settings) notificationSoundMode = AdMuteSettings.getNotificationSoundSettings(this@MainActivity) AnalyticsManager.logSettingsChanged("notification_sounds", "updated") setupStep = SetupStep.RUNNING }, onBack = { setupStep = SetupStep.RUNNING }, modifier = Modifier .padding(innerPadding) .background(MaterialTheme.colorScheme.background) ) } AnimatedVisibility( visible = setupStep == SetupStep.ABOUT, enter = fadeIn(animationSpec = tween(durationMillis = 240)), exit = fadeOut(animationSpec = tween(durationMillis = 220)) ) { AboutScreen( onBack = { setupStep = SetupStep.RUNNING }, modifier = Modifier.padding(innerPadding) ) } if (setupStep == SetupStep.THEME) { ThemeSelectionDialog( currentThemeMode = themeMode, onThemeSelected = { newThemeMode -> themeMode = newThemeMode AdMuteSettings.saveThemeMode(this@MainActivity, newThemeMode) AnalyticsManager.logSettingsChanged("theme_mode", newThemeMode.name) }, onDismiss = { setupStep = SetupStep.RUNNING } ) } } } } }
if ( setupStep == SetupStep.LOGS || setupStep == SetupStep.MODIFY_KEYWORDS || setupStep == SetupStep.ABOUT || setupStep == SetupStep.NOTIFICATION_SOUND || setupStep == SetupStep.THEME ) { BackHandler { setupStep = SetupStep.RUNNING } }
if (showSetupDonationDialog) { AlertDialog( onDismissRequest = { showSetupDonationDialog = false }, title = { Text("Support ADVOID") }, text = { Text("Thanks for completing setup. ADVOID is free to use — please consider supporting development with a donation.") }, confirmButton = { TextButton( onClick = { AnalyticsManager.logAction("donate_click") runCatching { startActivity(Intent(Intent.ACTION_VIEW, donationUrl.toUri())) } showSetupDonationDialog = false } ) { Text("Donate") } }, dismissButton = { TextButton(onClick = { showSetupDonationDialog = false }) { Text("Maybe later") } } ) } } } }
override fun onResume() { super.onResume() refreshPermissionStates() }
private fun refreshPermissionStates() { isPostNotificationsGranted = hasPostNotificationsPermission() isNotificationAccessGranted = hasNotificationListenerAccess() isBatteryOptimizationIgnored = isIgnoringBatteryOptimizations() }
private fun hasPostNotificationsPermission(): Boolean { if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) return true return ContextCompat.checkSelfPermission( this, android.Manifest.permission.POST_NOTIFICATIONS ) == PackageManager.PERMISSION_GRANTED }
private fun hasNotificationListenerAccess(): Boolean { val enabledListeners = Settings.Secure.getString(contentResolver, "enabled_notification_listeners") .orEmpty() return enabledListeners.contains(packageName) }
private fun isIgnoringBatteryOptimizations(): Boolean { val powerManager = getSystemService(PowerManager::class.java) ?: return false return powerManager.isIgnoringBatteryOptimizations(packageName) }
private fun requestDisableBatteryOptimization() { startActivity(Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS)) } }
@Composable private fun AppScreenContainer( title: String, subtitle: String, modifier: Modifier = Modifier, content: @Composable ColumnScope.() -> Unit ) { Column( modifier = modifier .fillMaxSize() .padding(horizontal = 16.dp, vertical = 12.dp), verticalArrangement = Arrangement.spacedBy(12.dp) ) { ElevatedCard(shape = RoundedCornerShape(20.dp)) { Column( modifier = Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(6.dp) ) { Text(text = title, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.SemiBold) Text(text = subtitle, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant) } } content() } }
@Composable fun IntroductionScreen( onStartSetup: () -> Unit, modifier: Modifier = Modifier ) { Box( modifier = modifier .fillMaxSize() .background(MaterialTheme.colorScheme.background) .padding(horizontal = 22.dp, vertical = 28.dp) ) { Column( modifier = Modifier.fillMaxSize(), horizontalAlignment = Alignment.CenterHorizontally ) { Spacer(modifier = Modifier.weight(0.48f)) Card( modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(24.dp), colors = CardDefaults.cardColors( containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.55f) ) ) { Column( modifier = Modifier .fillMaxWidth() .padding(horizontal = 26.dp, vertical = 36.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(22.dp) ) { Image( painter = painterResource(id = R.drawable.branding), contentDescription = "ADVOID branding", modifier = Modifier .fillMaxWidth(0.62f) .height(72.dp), contentScale = ContentScale.Fit ) Text( text = "ADVOID is an app which allows users\nto block disruptive ad audio automatically.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface, modifier = Modifier.fillMaxWidth(), textAlign = TextAlign.Center, lineHeight = 24.sp ) Text( text = "ADVOID helps users enjoy uninterrupted listening by muting ads from selected music apps and restoring media volume smoothly.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.fillMaxWidth(), textAlign = TextAlign.Center, lineHeight = 24.sp ) } } Spacer(modifier = Modifier.weight(1f)) Button( onClick = onStartSetup, modifier = Modifier .fillMaxWidth(0.86f) .height(56.dp), shape = RoundedCornerShape(16.dp), colors = ButtonDefaults.buttonColors( containerColor = MaterialTheme.colorScheme.secondary, contentColor = MaterialTheme.colorScheme.onSecondary ) ) { Text( text = "Start Setup", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold ) } } } }
@Composable fun WhitelistSelectionScreen( currentSelection: Set<String>, onContinue: (Set<String>) -> Unit, modifier: Modifier = Modifier, continueLabel: String = "Continue" ) { var otherAppsSearchQuery by remember { mutableStateOf("") } var isSearchFocused by remember { mutableStateOf(false) } var keyboardWasVisibleInSearchSession by remember { mutableStateOf(false) } val focusManager = LocalFocusManager.current val density = LocalDensity.current val recommendedPackages = remember { WhitelistedApps.recommendedPackages().values.toSet() } // If there is no saved selection (first-run), default to selecting all recommended packages var selectedPackages by remember(currentSelection, recommendedPackages) { mutableStateOf(if (currentSelection.isEmpty()) recommendedPackages else currentSelection) } val context = LocalContext.current val installedApps by produceState<List<InstalledApp>?>(initialValue = null, context, recommendedPackages) { value = withContext(Dispatchers.IO) { loadInstalledApps(context.packageManager, context.packageName, recommendedPackages) } } val isKeyboardVisible = WindowInsets.ime.getBottom(density) > 0 val shouldPrioritizeOtherApps = isSearchFocused && isKeyboardVisible val appsFadeInAlpha by animateFloatAsState( targetValue = if (installedApps == null) 0f else 1f, animationSpec = tween(durationMillis = 450), label = "apps-fade-in" )
if (installedApps == null) { WhitelistLoadingScreen(modifier = modifier) return }
val resolvedApps = installedApps.orEmpty() val recommendedApps = remember(resolvedApps) { resolvedApps.filter { WhitelistedApps.isRecommended(it.packageName, it.label) } } val otherApps = remember(resolvedApps) { resolvedApps.filterNot { WhitelistedApps.isRecommended(it.packageName, it.label) } } val filteredOtherApps = remember(otherApps, otherAppsSearchQuery) { val normalizedQuery = otherAppsSearchQuery.trim().lowercase() if (normalizedQuery.isBlank()) { otherApps } else { otherApps.filter { app -> app.label.lowercase().contains(normalizedQuery) || app.packageName.lowercase().contains(normalizedQuery) } } } LaunchedEffect(isKeyboardVisible, isSearchFocused) { if (isSearchFocused && isKeyboardVisible) { keyboardWasVisibleInSearchSession = true } if (isSearchFocused && !isKeyboardVisible && keyboardWasVisibleInSearchSession) { focusManager.clearFocus(force = true) isSearchFocused = false keyboardWasVisibleInSearchSession = false } if (!isSearchFocused) { keyboardWasVisibleInSearchSession = false } } BackHandler(enabled = isSearchFocused) { focusManager.clearFocus(force = true) }
AppScreenContainer( title = "Choose whitelisted apps", subtitle = "Only selected apps are scanned for ad notifications.", modifier = modifier.alpha(appsFadeInAlpha) ) { ElevatedCard( modifier = Modifier.weight(1f), shape = RoundedCornerShape(16.dp) ) { LazyColumn( modifier = Modifier.fillMaxSize(), contentPadding = PaddingValues(12.dp), verticalArrangement = Arrangement.spacedBy(6.dp) ) { item { AnimatedVisibility( visible = !shouldPrioritizeOtherApps, enter = fadeIn(animationSpec = tween(250)) + slideInVertically( animationSpec = tween(250), initialOffsetY = { -it / 4 } ), exit = fadeOut(animationSpec = tween(180)) + shrinkVertically(animationSpec = tween(180)) ) { Column(verticalArrangement = Arrangement.spacedBy(6.dp)) { SectionTitle("Recommended apps") if (recommendedApps.isEmpty()) { Text("No recommended apps found on this device.", style = MaterialTheme.typography.bodyMedium) } else { recommendedApps.forEach { app -> AppSelectionRow( app = app, checked = app.packageName in selectedPackages, onCheckedChange = { checked -> selectedPackages = if (checked) { selectedPackages + app.packageName } else { selectedPackages - app.packageName } } ) } } } } } item { AnimatedVisibility( visible = !shouldPrioritizeOtherApps, enter = fadeIn(animationSpec = tween(200)), exit = fadeOut(animationSpec = tween(180)) ) { HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp)) } SectionTitle("Other installed apps") } item { OutlinedTextField( value = otherAppsSearchQuery, onValueChange = { otherAppsSearchQuery = it }, modifier = Modifier .fillMaxWidth() .padding(bottom = 8.dp) .onFocusChanged { isSearchFocused = it.isFocused }, singleLine = true, keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done), keyboardActions = KeyboardActions( onDone = { focusManager.clearFocus(force = true) } ), label = { Text("Search other apps") }, placeholder = { Text("Type app name or package") } ) } if (filteredOtherApps.isEmpty()) { item { Text( text = if (otherAppsSearchQuery.isBlank()) { "No other installed apps found." } else { "No apps match \"$otherAppsSearchQuery\"." }, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant ) } } items(filteredOtherApps, key = { it.packageName }) { app -> AppSelectionRow( app = app, checked = app.packageName in selectedPackages, onCheckedChange = { checked -> selectedPackages = if (checked) selectedPackages + app.packageName else selectedPackages - app.packageName } ) } } }
Button(onClick = { onContinue(selectedPackages) }, modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(14.dp)) { Text(continueLabel) } } }
@Composable private fun SectionTitle(text: String) { Text(text = text, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.SemiBold) }
@Composable private fun WhitelistLoadingScreen(modifier: Modifier = Modifier) { val transition = rememberInfiniteTransition(label = "skeleton-transition") val pulseAlpha by transition.animateFloat( initialValue = 0.35f, targetValue = 0.75f, animationSpec = infiniteRepeatable( animation = tween(durationMillis = 850, easing = LinearEasing), repeatMode = RepeatMode.Reverse ), label = "skeleton-alpha" )
Column( modifier = modifier .fillMaxSize() .padding(horizontal = 16.dp, vertical = 12.dp), verticalArrangement = Arrangement.spacedBy(12.dp) ) { ElevatedCard(shape = RoundedCornerShape(20.dp)) { Column( modifier = Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(6.dp) ) { Text( text = "Choose whitelisted apps", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.SemiBold ) Text( text = "Scanning installed apps...", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant ) } }
ElevatedCard( modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(16.dp) ) { Column( modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(6.dp) ) { repeat(7) { Surface( modifier = Modifier .fillMaxWidth() .clip(RoundedCornerShape(12.dp)), color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.35f) ) { Row( modifier = Modifier.padding(horizontal = 10.dp, vertical = 10.dp), verticalAlignment = Alignment.CenterVertically ) { Box( modifier = Modifier .size(30.dp) .clip(RoundedCornerShape(6.dp)) .background( MaterialTheme.colorScheme.surfaceVariant.copy(alpha = pulseAlpha) ) ) Column( modifier = Modifier .weight(1f) .padding(start = 10.dp), verticalArrangement = Arrangement.spacedBy(6.dp) ) { Box( modifier = Modifier .fillMaxWidth(0.72f) .size(width = 176.dp, height = 22.dp) .clip(RoundedCornerShape(6.dp)) .background( MaterialTheme.colorScheme.surfaceVariant.copy(alpha = pulseAlpha) ) ) Box( modifier = Modifier .fillMaxWidth() .size(width = 300.dp, height = 18.dp) .clip(RoundedCornerShape(6.dp)) .background( MaterialTheme.colorScheme.surfaceVariant.copy(alpha = pulseAlpha * 0.9f) ) ) } } } } } } } }
