@Composable fun AdLogsScreen( onBack: () -> Unit, modifier: Modifier = Modifier ) { val context = LocalContext.current var logs by remember { mutableStateOf(AdMuteSettings.getAdLogs(context)) } var showClearLogsDialog by remember { mutableStateOf(false) } val dateFormatter = remember { SimpleDateFormat("HH:mm:ss, dd MMM", Locale.getDefault()) }
// Calculate total duration val totalDurationSeconds = remember(logs) { logs.sumOf { entry -> if (entry.endTime > entry.timestamp) { (entry.endTime - entry.timestamp) / 1000 } else { 0L } } }
val totalDurationFormatted = remember(totalDurationSeconds) { when { totalDurationSeconds < 60 -> "${totalDurationSeconds}s" totalDurationSeconds < 3600 -> { val minutes = totalDurationSeconds / 60 val seconds = totalDurationSeconds % 60 "${minutes}m ${seconds}s" } else -> { val hours = totalDurationSeconds / 3600 val minutes = (totalDurationSeconds % 3600) / 60 val seconds = totalDurationSeconds % 60 "${hours}h ${minutes}m ${seconds}s" } } }
AppScreenContainer( title = "Ad Detection Logs", subtitle = "History of detected ads and muted apps.", modifier = modifier.background(MaterialTheme.colorScheme.background) ) { if (logs.isNotEmpty()) { // Total time saved box ElevatedCard( modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(16.dp) ) { Column( modifier = Modifier .fillMaxWidth() .padding(16.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp) ) { Text( text = "Total Time ADBlock Saved", style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurfaceVariant, fontWeight = FontWeight.SemiBold ) Text( text = totalDurationFormatted, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary ) } } }
ElevatedCard( modifier = Modifier.weight(1f), shape = RoundedCornerShape(16.dp) ) { if (logs.isEmpty()) { Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) { Text(text = "No logs yet", style = MaterialTheme.typography.bodyLarge) } } else { LazyColumn( modifier = Modifier.fillMaxSize(), contentPadding = PaddingValues(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp) ) { items(logs) { entry -> Surface( shape = RoundedCornerShape(12.dp), color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.35f) ) { Column(modifier = Modifier.padding(12.dp)) { Row( modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween ) { Text( text = entry.appName, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary ) Column(horizontalAlignment = Alignment.End) { Text( text = dateFormatter.format(Date(entry.timestamp)), style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant ) if (entry.endTime > entry.timestamp) { val durationSec = (entry.endTime - entry.timestamp) / 1000 Text( text = "Duration: ${durationSec}s", style = MaterialTheme.typography.labelSmall, fontWeight = FontWeight.SemiBold, color = MaterialTheme.colorScheme.secondary ) } } } Spacer(modifier = Modifier.size(4.dp)) if (entry.content.isNotBlank()) { Text( text = entry.content, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface ) } else { Text( text = "Content hidden for privacy", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant ) } Text( text = entry.packageName, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f) ) } } } } } } Row( modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp) ) { OutlinedButton( onClick = { AnalyticsManager.logAction("clear_logs") showClearLogsDialog = true }, enabled = logs.isNotEmpty(), modifier = Modifier.weight(1f), shape = RoundedCornerShape(14.dp), colors = ButtonDefaults.outlinedButtonColors( disabledContainerColor = MaterialTheme.colorScheme.surface.copy(alpha = 0.3f), disabledContentColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.38f) ) ) { Text("Clear Logs") } Button( onClick = onBack, modifier = Modifier.weight(1f), shape = RoundedCornerShape(14.dp) ) { Text("Back") } } }
if (showClearLogsDialog) { AlertDialog( onDismissRequest = { showClearLogsDialog = false }, title = { Text("Clear logs?") }, text = { Text("Are you sure you want to clear all AD Detection Logs? This action cannot be undone.") }, confirmButton = { TextButton( onClick = { AdMuteSettings.clearAdLogs(context) logs = emptyList() showClearLogsDialog = false } ) { Text("Clear") } }, dismissButton = { TextButton(onClick = { showClearLogsDialog = false }) { Text("Cancel") } } ) } }
