ElevatedCard(shape = RoundedCornerShape(16.dp)) { if (noMusicPlaying) { Box( modifier = Modifier .fillMaxWidth() .height(90.dp) .background(MaterialTheme.colorScheme.surfaceVariant), contentAlignment = Alignment.Center ) { Text( text = "No media is playing currently", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold ) } } else { val info = nowPlayingInfo Row( modifier = Modifier .fillMaxWidth() .height(100.dp) .background(MaterialTheme.colorScheme.surfaceVariant), verticalAlignment = Alignment.CenterVertically ) { Box( modifier = Modifier .size(100.dp) .clip(RoundedCornerShape(topStart = 16.dp, bottomStart = 16.dp)) ) { if (albumArtBitmap != null) { Image( bitmap = albumArtBitmap.asImageBitmap(), contentDescription = "Album art", modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop, filterQuality = FilterQuality.High ) } else { Box( modifier = Modifier .fillMaxSize() .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.2f)), contentAlignment = Alignment.Center ) { Text( text = "♪", style = MaterialTheme.typography.headlineLarge, color = MaterialTheme.colorScheme.primary ) } } appIconBitmap?.let { icon -> Surface( modifier = Modifier .align(Alignment.BottomEnd) .padding(4.dp) .size(24.dp), shape = RoundedCornerShape(6.dp), color = MaterialTheme.colorScheme.surface ) { Image( bitmap = icon.asImageBitmap(), contentDescription = "${info.appName} icon", modifier = Modifier .fillMaxSize() .padding(2.dp), contentScale = ContentScale.Crop ) } } }
Column( modifier = Modifier .weight(1f) .padding(horizontal = 16.dp, vertical = 8.dp), verticalArrangement = Arrangement.Center ) { Text( text = info.title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurfaceVariant, maxLines = 1 ) Spacer(modifier = Modifier.height(2.dp)) Text( text = info.text, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant, maxLines = 1 ) if (info.subText.isNotBlank()) { Text( text = info.subText, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f), maxLines = 1 ) } } } } } }
@Composable private fun CooldownSettingsScreen( currentCooldownMinutes: Int, onSave: (Int) -> Unit, onBack: () -> Unit, modifier: Modifier = Modifier ) { var cooldownMinutes by remember(currentCooldownMinutes) { mutableStateOf(currentCooldownMinutes) } Box( modifier = modifier .fillMaxSize() .background(Color.Black.copy(alpha = 0.2f)) .padding(horizontal = 20.dp), contentAlignment = Alignment.Center ) { ElevatedCard( shape = RoundedCornerShape(20.dp), modifier = Modifier.fillMaxWidth(0.92f) ) { Column( modifier = Modifier .fillMaxWidth() .padding(horizontal = 18.dp, vertical = 20.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(12.dp) ) { Text( text = "Cooldown settings", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold, textAlign = TextAlign.Center ) Text( text = "Swipe the number up/down to set 1 to 10 minutes.", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant, textAlign = TextAlign.Center ) Row( modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.Center, verticalAlignment = Alignment.CenterVertically ) { CooldownNumberRoller( minutes = cooldownMinutes, onValueChange = { cooldownMinutes = it } ) Text( text = "min", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold, modifier = Modifier.padding(start = 12.dp) ) } Button( onClick = { onSave(cooldownMinutes.coerceIn(1, 10)) }, modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(14.dp) ) { Text("Save") } OutlinedButton( onClick = onBack, modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(14.dp) ) { Text("Back") } } } } }
@Composable private fun CooldownNumberRoller( minutes: Int, onValueChange: (Int) -> Unit, modifier: Modifier = Modifier ) { val minValue = 1 val maxValue = 10 var accumulatedDrag by remember { mutableStateOf(0f) }
val previousValue = (minutes - 1).takeIf { it >= minValue } val nextValue = (minutes + 1).takeIf { it <= maxValue } val previousAlpha by animateFloatAsState(targetValue = if (previousValue == null) 0f else 0.5f, label = "prev-alpha") val nextAlpha by animateFloatAsState(targetValue = if (nextValue == null) 0f else 0.5f, label = "next-alpha")
Column( modifier = modifier.pointerInput(minutes) { detectVerticalDragGestures( onVerticalDrag = { change, dragAmount -> accumulatedDrag += dragAmount val stepThresholdPx = 24f
while (abs(accumulatedDrag) >= stepThresholdPx) { val steppingDown = accumulatedDrag > 0 val candidate = if (steppingDown) minutes - 1 else minutes + 1 onValueChange(candidate.coerceIn(minValue, maxValue)) accumulatedDrag += if (steppingDown) -stepThresholdPx else stepThresholdPx } change.consume() }, onDragEnd = { accumulatedDrag = 0f }, onDragCancel = { accumulatedDrag = 0f } ) }, horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(2.dp) ) { Text( text = previousValue?.toString() ?: "", style = MaterialTheme.typography.titleMedium, color = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.alpha(previousAlpha) ) AnimatedContent( targetState = minutes, transitionSpec = { if (targetState > initialState) { (slideInVertically { it / 2 } + fadeIn() + scaleIn(initialScale = 0.82f)) .togetherWith(slideOutVertically { -it / 2 } + fadeOut() + scaleOut(targetScale = 1.18f)) } else { (slideInVertically { -it / 2 } + fadeIn() + scaleIn(initialScale = 0.82f)) .togetherWith(slideOutVertically { it / 2 } + fadeOut() + scaleOut(targetScale = 1.18f)) } }, label = "cooldown-roller" ) { value -> Text( text = value.toString(), style = MaterialTheme.typography.displayMedium, fontWeight = FontWeight.Bold ) } Text( text = nextValue?.toString() ?: "", style = MaterialTheme.typography.titleMedium, color = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.alpha(nextAlpha) ) } }
@Composable private fun NotificationSoundSettingsScreen( currentSettings: NotificationSoundSettings, onSave: (NotificationSoundSettings) -> Unit, onBack: () -> Unit, modifier: Modifier = Modifier ) { var inSound by remember(currentSettings) { mutableStateOf(currentSettings.inSound) } var outSound by remember(currentSettings) { mutableStateOf(currentSettings.outSound) } val context = LocalContext.current val isLandscape = LocalConfiguration.current.orientation == Configuration.ORIENTATION_LANDSCAPE var previewPlayer by remember { mutableStateOf<MediaPlayer?>(null) }
fun stopPreview() { previewPlayer?.release() previewPlayer = null }
fun playPreview(config: NotificationSoundConfig) { stopPreview() when (config.source) { NotificationSoundSource.OFF -> Unit NotificationSoundSource.STOCK -> { runCatching { val attributes = AudioAttributes.Builder() .setUsage(AudioAttributes.USAGE_NOTIFICATION) .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION) .build() val player = MediaPlayer.create(context, config.stockSound.resId, attributes, 0) ?: return@runCatching previewPlayer = player player.setOnCompletionListener { if (previewPlayer === it) previewPlayer = null it.release() } player.setOnErrorListener { mp, _, _ -> if (previewPlayer === mp) previewPlayer = null mp.release() true } player.start() } } NotificationSoundSource.CUSTOM -> { val uriText = config.customUri ?: return runCatching { val player = MediaPlayer().apply { setDataSource(context, uriText.toUri()) setAudioAttributes( AudioAttributes.Builder() .setUsage(AudioAttributes.USAGE_NOTIFICATION) .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION) .build() ) setOnCompletionListener { if (previewPlayer === it) previewPlayer = null it.release() } setOnErrorListener { mp, _, _ -> if (previewPlayer === mp) previewPlayer = null mp.release() true } prepare() previewPlayer = this start() } player } } } }
DisposableEffect(Unit) { onDispose { stopPreview() } }
BackHandler { stopPreview() onBack() }
