private fun loadInstalledApps( packageManager: PackageManager, ownPackageName: String, recommendedPackages: Set<String> ): List<InstalledApp> { val launcherIntent = Intent(Intent.ACTION_MAIN).apply { addCategory(Intent.CATEGORY_LAUNCHER) } val resolveInfos = packageManager.queryIntentActivities(launcherIntent, 0)
val launcherApps = resolveInfos.mapNotNull { info -> val activityInfo = info.activityInfo ?: return@mapNotNull null val packageName = activityInfo.packageName if (packageName == ownPackageName) return@mapNotNull null val label = info.loadLabel(packageManager).toString().ifBlank { packageName } val icon = runCatching { packageManager.getApplicationIcon(packageName) }.getOrNull() InstalledApp(label, packageName, icon?.toBitmapSafely()) }
val recommendedInstalledApps = recommendedPackages.mapNotNull { packageName -> if (packageName == ownPackageName) return@mapNotNull null try { val appInfo = packageManager.getApplicationInfo(packageName, 0) val label = packageManager.getApplicationLabel(appInfo).toString().ifBlank { packageName } val icon = runCatching { packageManager.getApplicationIcon(packageName) }.getOrNull() InstalledApp(label, packageName, icon?.toBitmapSafely()) } catch (_: NameNotFoundException) { null } }
return (launcherApps + recommendedInstalledApps) .distinctBy { it.packageName } .sortedBy { it.label.lowercase() } }
private fun NotificationSoundConfig.summaryLabel(): String { return when (source) { NotificationSoundSource.OFF -> "Off" NotificationSoundSource.STOCK -> stockSound.label NotificationSoundSource.CUSTOM -> customDisplayName ?: "Custom sound" } }
private fun Drawable.toBitmapSafely(): Bitmap { if (this is BitmapDrawable && bitmap != null) { return bitmap } val width = intrinsicWidth.takeIf { it > 0 } ?: 96 val height = intrinsicHeight.takeIf { it > 0 } ?: 96 val bitmap = createBitmap(width, height, Bitmap.Config.ARGB_8888) val canvas = Canvas(bitmap) setBounds(0, 0, canvas.width, canvas.height) draw(canvas) return bitmap }
private fun android.content.ContentResolver.takePersistablePermissionSafely(uri: Uri) { runCatching { takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION) } }
private fun android.content.ContentResolver.resolveDisplayName(uri: Uri): String { return runCatching { query(uri, arrayOf(OpenableColumns.DISPLAY_NAME), null, null, null)?.use { cursor -> val index = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME) if (index >= 0 && cursor.moveToFirst()) { return@runCatching cursor.getString(index) } null } }.getOrNull() ?: "Custom sound" }
