@Composable private fun ThemeRoller( currentTheme: ThemeMode, onThemeChange: (ThemeMode) -> Unit, modifier: Modifier = Modifier ) { val themes = listOf(ThemeMode.SYSTEM, ThemeMode.LIGHT, ThemeMode.DARK) val themeIndex = themes.indexOf(currentTheme).takeIf { it >= 0 } ?: 0 val minThemeIndex = 0 val maxThemeIndex = themes.size - 1 var accumulatedDrag by remember { mutableStateOf(0f) }
val previousThemeIndex = (themeIndex - 1).takeIf { it >= minThemeIndex } val nextThemeIndex = (themeIndex + 1).takeIf { it <= maxThemeIndex } val previousTheme = previousThemeIndex?.let { themes.getOrNull(it) } val nextTheme = nextThemeIndex?.let { themes.getOrNull(it) } val previousAlpha by animateFloatAsState(targetValue = if (previousTheme == null) 0f else 0.5f, label = "prev-theme-alpha") val nextAlpha by animateFloatAsState(targetValue = if (nextTheme == null) 0f else 0.5f, label = "next-theme-alpha")
Column( modifier = modifier.pointerInput(themeIndex) { detectVerticalDragGestures( onVerticalDrag = { change, dragAmount -> accumulatedDrag += dragAmount val stepThresholdPx = 24f
while (abs(accumulatedDrag) >= stepThresholdPx) { val steppingDown = accumulatedDrag > 0 val candidate = if (steppingDown) themeIndex - 1 else themeIndex + 1 val newIndex = candidate.coerceIn(minThemeIndex, maxThemeIndex) onThemeChange(themes[newIndex]) accumulatedDrag += if (steppingDown) -stepThresholdPx else stepThresholdPx } change.consume() }, onDragEnd = { accumulatedDrag = 0f }, onDragCancel = { accumulatedDrag = 0f } ) }, horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(2.dp) ) { Text( text = previousTheme?.label ?: "", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.alpha(previousAlpha) ) AnimatedContent( targetState = currentTheme, transitionSpec = { if (themes.indexOf(targetState) > themes.indexOf(initialState)) { (slideInVertically { it / 2 } + fadeIn() + scaleIn(initialScale = 0.82f)) .togetherWith(slideOutVertically { -it / 2 } + fadeOut() + scaleOut(targetScale = 1.18f)) } else { (slideInVertically { -it / 2 } + fadeIn() + scaleIn(initialScale = 0.82f)) .togetherWith(slideOutVertically { it / 2 } + fadeOut() + scaleOut(targetScale = 1.18f)) } }, label = "theme-roller" ) { theme -> Text( text = theme.label, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold ) } Text( text = nextTheme?.label ?: "", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant, modifier = Modifier.alpha(nextAlpha) ) } }
